struct H2Stream{int32_t cid=-1,uid=-1;uint64_t flow=0;int status=0;Headers requestHeaders,responseHeaders,requestTrailers,responseTrailers;std::string method,path,authority,req,res;bool requestEnd=false,responseEnd=false,submitted=false;int64_t started=nowMs();size_t headerBytes=0;};
