nghttp2_ssize bodyRead(nghttp2_session* session,int32_t id,uint8_t* buf,size_t len,uint32_t* flags,nghttp2_data_source* src,void*){auto* s=static_cast<H2Stream*>(src->ptr);return drain(session,id,s->req,s->requestEnd,s->requestTrailers,buf,len,flags);}
nghttp2_ssize responseRead(nghttp2_session* session,int32_t id,uint8_t* buf,size_t len,uint32_t* flags,nghttp2_data_source* src,void*){auto* s=static_cast<H2Stream*>(src->ptr);return drain(session,id,s->res,s->responseEnd,s->responseTrailers,buf,len,flags);}
nghttp2_ssize sendCallback(nghttp2_session* session,const uint8_t* data,size_t n,int,void* user){auto* b=static_cast<Bridge*>(user);auto* ssl=session==b->cs?b->client.ssl:b->upstream.ssl;int wrote=SSL_write(ssl,data,int(n));if(wrote>0)return wrote;int e=SSL_get_error(ssl,wrote);return (e==SSL_ERROR_WANT_READ||e==SSL_ERROR_WANT_WRITE)?NGHTTP2_ERR_WOULDBLOCK:NGHTTP2_ERR_CALLBACK_FAILURE;}
int beginHeaders(nghttp2_session* session,const nghttp2_frame* frame,void* user){auto* b=static_cast<Bridge*>(user);try{if(session==b->cs&&frame->headers.cat==NGHTTP2_HCAT_REQUEST){if(b->all.size()>=2048)throw std::runtime_error("HTTP/2 connection stream limit (2048)");auto s=std::make_unique<H2Stream>();s->cid=frame->hd.stream_id;b->clients[s->cid]=s.get();b->all.push_back(std::move(s));}else if(session==b->us&&b->upstreams.count(frame->hd.stream_id)){auto* s=b->upstreams[frame->hd.stream_id];if(!s->submitted){s->responseHeaders.clear();s->status=0;}}return 0;}catch(const std::exception& e){b->error=e.what();return NGHTTP2_ERR_CALLBACK_FAILURE;}}
