        s->flow=b->store.createFlow({{"host",b->host},{"port",b->port},{"path",s->path},{"method",s->method},{"protocol","HTTP/2"},{"connection",b->connection},{"streamId",s->cid},{"packetKeys",b->keys},{"tls",SSL_get_version(b->client.ssl)}},s->requestHeaders);
